"""Generate the research report from measured artifacts, without invented claims."""
from common import ROOT, OUT, records
from analyse import load, stats, table
import numpy as np

NA='Not measurable with current implementation'
def pct(x):return f'{x*100:.2f}%' if x is not None else NA
def milliseconds(x):return f'{x:.2f} ms' if x is not None else NA

def main():
    s=load(OUT/'processed/summary.json');env=load(OUT/'raw/environment.json');browser=records(OUT/'raw/browser_trials.jsonl');diverse=records(OUT/'raw/browser_diverse.jsonl');scale=records(OUT/'raw/scalability.jsonl')
    complete=[r for r in browser if r['kind']=='consecutive'];time_to_sign=stats([r['ttfs_ms'] for r in browser if r.get('success') and r['kind']=='latency']);prepared=stats([r['prepared_ms'] for r in browser if r.get('success') and r['kind']=='latency'])
    thirteen=next(r for r in s['browser_latency'] if r['clips']==13)
    summary=[('Template Accuracy',pct(s['classification']['accuracy'])),('Template Macro F1',pct(s['classification']['macro_f1'])),('Template Weighted F1',pct(s['classification']['weighted_f1'])),('Entity Extraction F1',pct(s['entities']['micro']['f1'])),('Safety Validation F1 (integrated timetable)',NA),('Safety False Negative Rate (integrated timetable)',NA),('Retrieval Accuracy (35 engineering probes)',pct(s['retrieval']['probe_accuracy'])),('Recall@1',NA),('Recall@3',NA),('Recall@5',NA),('Translation Coverage (lexical retention proxy)',pct(s['retrieval']['lexical_coverage'])),('Fingerspelling Rate (represented units)',pct(s['retrieval']['fingerspelling_rate'])),('Mean End-to-End Preparation Latency (repeated-motion workload)',milliseconds(prepared['mean'] if prepared else None)),('P95 Preparation Latency (repeated-motion workload)',milliseconds(prepared['p95'] if prepared else None)),('Time-to-First-Sign (repeated-motion workload)',milliseconds(time_to_sign['mean'] if time_to_sign else None)),('13 Clip Processing Time (repeated TRAIN, mean preparation)',milliseconds((thirteen['preparation_ms'] or {}).get('mean'))),('Transition Improvement',NA),('Average Avatar FPS (rAF estimate)',f"{s['avatar']['mean_fps']:.2f}" if s['avatar']['mean_fps'] else NA)]
    table('final_summary',[dict(metric=k,measured_result=v) for k,v in summary])
    text=['# Signora experimental evaluation', '', 'This report evaluates the current implementation; it does not validate the linguistic correctness of ISL. No runtime retrieval, approval, avatar or display implementation was changed to improve results. The experiment uses the existing development preview, with unreviewed motions and partial output permitted.', '', '## Environment and provenance', '',f"Baseline: `{env['timestamp']}`, Python {env['python']}, {env['hardware']['os']}; CPU {env['hardware']['cpu']['Name']}, {env['hardware']['ram']/1024**3:.2f} GiB RAM. GPU devices: "+', '.join(g['Name'] for g in env['hardware']['gpu'])+'.', '',f"PostgreSQL: {env['database']['version']}; baseline database {env['database']['size_bytes']:,} bytes, schema `{env['database']['schema']}`. Registered concepts/motions: {env['counts']['sign_concepts']}/{env['counts']['motion_versions']}; unique GLB objects: {env['unique_glb_objects']}. Eligible production motions, embeddings and retrieval profiles: all zero. Full dependency/runtime configuration is in `raw/environment.json`; it contains no credentials.", '', 'Browser runs use headless Chromium with a 1280×900 viewport and the unsafe-SwiftShader fallback flag. Browser version and renderer identity are recorded in browser environment JSON files where captured. rAF measurements are not hardware GPU performance counters. Existing station services remain running, so these are local-system measurements, not isolated laboratory timing.', '', 'The working tree was committed during the session interruption. `raw/source_integrity_after_commit.json` distinguishes line-ending normalization from the one changed realtime-delivery source file. Core parser, gloss, selector, asset store and avatar controller hashes remained unchanged. Realtime changes are not attributed to this evaluation. Research scripts and result artifacts are the evaluation modifications.', '', '## Dataset and metrics', '',f"{s['dataset']['cases']} cases; {s['dataset']['unique_texts']} distinct texts; {s['dataset']['families']} phrasing families; 32 cases per class. The set is author-labelled and synthetic. It includes 22 repeated notices/value variants, so results must not be presented as 224 independent real-world observations. Fourteen distinct cases were added to the initial 210-case set to exceed 200 distinct texts. No output was used as a class label.", '', 'Classification measures the typed `meaning.intent`; unsupported input is ABSTAIN, even if lexical recovery can play clips. Entity extraction includes typed slots and explicit singleton partial-recovery slots. Names are scored as extracted raw names, not successful resolution to configured station IDs. Old/new platform roles are scored separately. Exact match is over the union of expected and observed fields; true-negative absent fields are not used to inflate it.', '', 'Lexical coverage checks complete catalog-label or alphabet/digit representation of independently required units. It does not certify sign meaning, word order, timing, negation scope, visual legibility, or comprehension. Partial spelling is not full coverage. The retrieval probe score checks decoded catalog identities on 35 declared queries, including one function-word omission control. Ranked Recall@k is unavailable for this preview; there is no approved indexed corpus for the separate candidate-search endpoint.', '', '## Measured summary', '', '| Metric | Measured result |','|---|---:|', *[f'| {k} | {v} |' for k,v in summary], '', 'Detailed per-class precision/recall/F1 and entity metrics are in `tables/classification_metrics.csv` and `tables/entity_metrics.csv`. Case outputs, selected motion IDs, normalization, gloss and missing units are retained in raw API responses and `processed/gloss_traces.json`.', '', '## Classification and entity failures', '']
    for r in s['classification']['per_class']:text.append(f"- {r['category']}: F1 {pct(r['f1'])}, recall {pct(r['recall'])}, support {r['support']}; {r['fn']} missed/abstained cases.")
    text+=['','Emergency and Other have no typed intent in the parser contract. Lexical playback does not turn those cases into successful semantic classifications. Train names and platform-change roles expose extraction gaps. Inspect `processed/entity_failures.json` for exact examples; confidence in a small number of time examples must not be generalized to arbitrary timetables.', '', '## Safety scope and false negatives', '']
    g=s['safety_guard'];text += [f"The existing candidate compatibility guard was tested on 60 conflicting pairs and 10 matching controls: TP={g['tp']}, TN={g['tn']}, FP={g['fp']}, **FN={g['fn']}**, precision={pct(g['precision'])}, recall={pct(g['recall'])}, F1={pct(g['f1'])}, false-negative rate={pct(g['false_negative_rate'])}.", '', '**This is not integrated safety validation.** `AnnouncementInput` has no trusted timetable payload, and development preview bypasses production review blocking. The guard operates in the separate candidate-search path. These constructed pairs do not prove that false operational announcements are prevented. Integrated safety F1 and false-negative rate are unavailable.', '', '## Retrieval, fallback and gloss', '', f"Required annotated units represented: {s['retrieval']['represented_required']}/{s['retrieval']['required_units']} ({pct(s['retrieval']['lexical_coverage'])}). Fingerspelled units: {s['retrieval']['spelled_units']}/{s['retrieval']['represented_units']} ({pct(s['retrieval']['fingerspelling_rate'])}). The label-equivalence audit flags {s['retrieval']['unnecessary_fingerspelling']} cases where an existing equivalent catalog label was available; these are saved for inspection and are not expert judgements.", '', 'Fallback evidence in `raw/fallbacks.json` removes a phrase or word from an evaluation-only candidate list and reruns the actual selector. Existing phrase, word, digits and alphabet motions are used. No library item is deleted. No complete sentence motion exists in this catalog, so sentence-available fallback and sentence-specific gains cannot be demonstrated.', '', 'The default gloss order is a draft engineering rule. Function words are intentionally omitted when not consumed by a phrase. The mandatory `Train 1201 arrives at platform 2` case is retained under the `mandatory` raw API result, with its actual motion IDs. Successful spelling of a concept is weaker evidence than selecting an appropriate lexical sign.', '', '## Browser playback and latency', '',f"Repeated-motion series: {sum(r['attempts'] for r in s['browser_latency'])} attempts, {sum(r['successful'] for r in s['browser_latency'])} movement-verified successes. Consecutive series: {s['consecutive']['completed']}/{s['consecutive']['attempts']} completed, with persistent avatar identity checked. The series includes one-, two- and eight-clip messages. No forced GC/reload or time-scale acceleration was used.", '', 'A movement check requires changing rendered bone-pose hashes and advancing mixer time; API 200 alone is insufficient. The application samples pose hashes every 250 ms, adding observation delay to time-to-first-sign. Animation duration and preparation latency are different quantities. Length trials stop only after movement has been observed; the separate consecutive run waits for COMPLETE and checks all clips finished.', '', '| Clips | Attempts / successes | Mean preparation (ms) | Mean first sign (ms) | P95 first sign (ms) |','|---:|---:|---:|---:|---:|']
    for r in s['browser_latency']:
        text.append(f"| {r['clips']} | {r['attempts']} / {r['successful']} | {(r['preparation_ms'] or {}).get('mean',float('nan')):.2f} | {(r['ttfs_ms'] or {}).get('mean',float('nan')):.2f} | {(r['ttfs_ms'] or {}).get('p95',float('nan')):.2f} |")
    text+=['','These timings reuse TRAIN and therefore mostly measure warm-cache preparation. Their weak dependence on sequence length is not evidence of sub-linear diverse-asset loading. The first cold-session trial is retained rather than silently discarded. Mean, median, min, max, sample standard deviation and P95 are in `tables/latency_summary.csv`.','', '### Distinct-motion sensitivity series', '']
    diverse_summary=[]
    for n in [1,5,10,13,20,30]:
        trials=[r for r in diverse if r['n']==n];good=[r for r in trials if r.get('success')];st=stats([r['ttfs_ms'] for r in good]);pr=stats([r['prepared_ms'] for r in good]);warm=stats([r['prepared_ms'] for r in good if r['trial']>0]);cold=next((r['prepared_ms'] for r in good if r['trial']==0),None)
        diverse_summary.append(dict(clips=n,attempts=len(trials),successes=len(good),cold_first_preparation_ms=cold,warm_preparation_ms=warm,all_preparation_ms=pr,ttfs_ms=st))
        text.append(f"- {n} distinct motions: {len(good)}/{len(trials)} successes; mean preparation {milliseconds(pr['mean'] if pr else None)}, first-use preparation {milliseconds(cold)}, subsequent-trial mean {milliseconds(warm['mean'] if warm else None)}.")
    from common import save
    save(OUT/'processed/diverse_latency.json',diverse_summary)
    text += ['', 'The approximately four-second / 12–13-clip claim is workload- and cache-dependent, not a fixed property of the system. Compare the measured 13-clip repeated and distinct-motion groups above. No value was hardcoded to reproduce that observation.', '', f"Average rAF FPS: {s['avatar']['mean_fps']:.2f}; minimum instantaneous FPS: {s['avatar']['min_instantaneous_fps']:.2f}; P95 frame interval: {s['avatar']['frame_ms']['p95']:.2f} ms. Estimated missed 60-Hz opportunities: {s['avatar']['estimated_missed_60hz_opportunities']:,}. This estimate is not an actual GPU dropped-frame counter.", '', 'JavaScript heap and CDP performance metrics are recorded per trial; process RSS/CPU time are sampled in the distinct-motion run. Heap growth alone does not prove a leak because garbage collection and cached clips remain live. Texture counts and maximum texture size are captured from the actual avatar. GPU utilization is not directly measured.', '', '## Transition measurements and ablations', '']
    p=OUT/'raw/transition_endpoints.json'
    if p.exists():
        tr=load(p);pairs=tr['pairs'];weights=[r['occurrences'] for r in pairs]
        for key in ['mean_joint_angle_degrees','mean_joint_displacement_model_units','mean_hand_displacement_model_units','mean_hand_velocity_jump_model_units_per_second']:
            valid=[r for r in pairs if r[key] is not None]
            text.append(f"- {key}: {np.average([r[key] for r in valid],weights=[r['occurrences'] for r in valid]):.6f} (occurrence-weighted)." if valid else f'- {key}: {NA}.')
        text += ['',f"Measured {len(pairs)} distinct source-GLB transition pairs. Endpoint quaternion differences and model-space joint/hand displacements characterize cuts, not perceptual naturalness. The 40-ms velocity estimate uses spherical quaternion interpolation. No optimized selection exists, so percentage improvement cannot be calculated."]
    text+=['','Ablations disable spelling and numeric units only inside an evaluation namespace and restrict multiword candidates for Word-only. Production code is unchanged. Phrase+Word and Sentence+Phrase+Word have the same available catalog because there are no sentence records; identical results are not evidence that sentence retrieval is ineffective. E (transition-aware) is unimplemented. Do not interpret the small, authored 35-query probe set as an ISL-quality benchmark.', '', '## Scalability', '','| Entries | Synthetic | Mean catalog + selection (ms) | Trials |','|---:|---|---:|---:|']
    for r in sorted(scale,key=lambda x:x['requested_rows']):text.append(f"| {r['requested_rows']} | {r['synthetic']} | {np.mean([x['combined_ms'] for x in r['trials']]):.2f} | {len(r['trials'])} |")
    text+=['','The actual development catalog SELECT, ORM materialization, candidate construction and selector were timed. Larger sizes duplicate vocabulary and metadata identities in connection-private PostgreSQL temporary tables; GLB files are shared, not duplicated. Timing excludes synthetic setup, aliases, HTTP and asset verification/download. This is not an API or semantic-ANN scalability result. Temporary tables are rolled back after every size. The runtime role correctly denied temporary-table creation; the local maintenance account was used without changing permissions. An initial slow synthetic setup was cancelled and corrected to avoid repeatedly serializing unused large metadata; no runtime query was optimized.', '', '## Graph interpretation', '', '1. **Core system:** Separate task metrics; no composite accuracy. High lexical retention or small-probe identity accuracy can coexist with weak typed-intent classification. Integrated safety is N/A.', '2. **Retrieval:** Top-k columns are N/A because the tested sequence API has no ranking. The identity and coverage columns measure different labelled datasets.', '3. **Announcement types:** Compare the per-class F1 values above; unsupported Emergency/Other intents remain visible as failures rather than being hidden by lexical playback.', '4. **Latency vs clips:** Repeated-asset caching dominates this curve; do not fit a scaling law from these six means. The distinct-motion sensitivity data tests a different loading workload.', '5. **Pipeline breakdown:** Parser timing combines detection, entity extraction and validation. Inclusive normalization timings overlap it. These bars are not an additive decomposition; separate GLB/decode/stitch/render stages remain unavailable without invasive instrumentation.', '6. **Ablations:** Numeric/alphabet fallback changes engineering coverage; sentence and transition-specific gains cannot be demonstrated with the present catalog/implementation.', '7. **Retrieval levels:** Percentages are per output clip, so spelling a long word contributes many letters. Compare with unit-level fingerspelling rate before interpreting dependence.', '8. **Transitions:** Only existing full-clip cuts have measured endpoint discontinuity. The missing optimized bar must not be reported as zero or a percentage gain.', '9. **Scalability:** The full eligible-catalog scan/materialization grows with duplicated row count. These synthetic measurements do not establish performance on a diverse 100K-sign language library.', '10. **Safety:** Counts and metrics belong only to the candidate compatibility guard. They cannot support a claim that the live preview detects inaccurate trusted railway facts.', '11. **Confusion matrix:** ABSTAIN is an extra prediction column so parser rejection is visible. It is not relabelled as Other.', '', '## Assessment and limitations', '', '- **Working in the measured scope:** local text API, actual GLB loading, persistent-avatar movement, sequential playback, available-word/digit/alphabet fallback, 50 consecutive complete previews.', '- **Implemented but constrained:** regex semantic parser, raw entity extraction, draft gloss ordering, staged-motion retrieval, review/publication controls, station-specific display assignments.', '- **Missing or not measurable:** integrated trusted timetable safety, populated approved semantic retrieval corpus, sentence-level motion corpus, transition-aware variant optimization, top-k preview ranking, exact separated stage timing and hardware GPU usage.', '- **Failed / needs improvement:** typed intent abstentions, unsupported Emergency/Other classes, train-name extraction, wrong/ambiguous lexical place roles, partial semantic coverage and some unnecessary spelling. Exact cases are retained; no runtime patch hides them.', '- **Voice:** inspect the separate synthetic-audio smoke evidence if present; a synthetic voice test is not natural speech recognition accuracy or station-noise robustness.', '- **ISL expert evaluation:** Requires human participant evaluation.', '- **Deaf-user comprehension, naturalness and satisfaction:** Requires human participant evaluation.', '', '## Reproduction', '', 'See `scripts/run-evaluation.ps1`. Prerequisites: existing local services, local credentials kept outside the repository, registered GLBs, Playwright Chromium, and evaluation-only Python dependencies under `artifacts/research-python`. Scripts checkpoint raw attempts. Use a fresh evidence directory for an independent replication; do not silently append retries to passing samples. App requests create ordinary private preview records; no library version is modified, activated or deleted, and no announcement is broadcast.', '', 'Do not publish raw local credentials. All thirteen PNG charts (eleven requested plus two sensitivity/profile charts) have adjacent JSON data, and the chart generator is `scripts/graphs.py`. Tables and raw responses are the authoritative evidence; screenshots are illustrative.']
    text += ['', '## Final verification and retained failures', '',
        'Station display counts are dynamic, not fixed at five. The isolated seven-display suite passed 98 tests with two opt-in tests skipped; a separate three-display run passed its control integration test with the browser test skipped. These tests cover independent targeting, broadcast, stopping a selected display, replay/idempotency, station/role scope and assignment. They are backend integration evidence, not a claim of simultaneous physical-screen testing. Frontend unit tests: 67 passed.', '',
        'The first backend test run from the backend directory loaded its local .env and failed the unconfigured-ASR expectation (93 passed, one failed). The root-directory isolated rerun passed. Both XML results are retained. No application change was made to conceal that environment issue.', '',
        'The distinct-motion browser series contains 120 successful trials and one retained failed harness attempt: movement was observed, but playback completed before the harness clicked Stop. The evaluation harness was corrected to tolerate an already-completed sequence and the trial was retried. The failed record and screenshot remain available.', '',
        'Safety challenge-set QA replaced cancellation examples confounded by changed numeric fields with same-train positive/negative cancellation pairs, and added ten destination-only adversarial pairs. Those ten exposed the guard false negatives. Initial data are retained separately. This is exploratory authored testing, not a held-out representative safety benchmark.']
    voice_path=OUT/'raw/voice_api.json'
    if voice_path.exists():
        voice=load(voice_path)
        text += ['', '### Synthetic voice smoke', '', f"Direct ASR HTTP {voice['http_status']}; measured ASR duration {voice['asr_ms']:.2f} ms; transcript: {voice['response'].get('text', '')!r}. Voice translation HTTP {voice.get('translation_http_status', 'not attempted')}. This is one synthetic English recording, not human/noise accuracy evidence."]
    verification=OUT/'raw/voice_browser/verification.json'
    if verification.exists():
        result=load(verification)
        text.append(f"Browser smoke: {result['status']}. " + '; '.join(f"{r['name']}: {r['clip_count']} clips completed, rendered bone movement and advancing mixer verified" for r in result['measurements']) + '.')
        response_path=OUT/'raw/voice_browser/voice-response.json'
        if response_path.exists():
            response=load(response_path)
            text.append(f"Browser-captured transcript: {response['original_text']!r}. Chromium's fake audio stream loops independently of the Record button; this recording captured a rotated/partial utterance. Its successful lexical playback verifies microphone upload, ASR, retrieval and animation transport, not correct reconstruction of the complete announcement. The separate whole-WAV ASR result above preserves the complete sentence.")
    elif (OUT/'raw/voice_browser/failure.json').exists():
        text.append('Browser voice smoke failed; inspect raw/voice_browser/failure.json. No successful voice-avatar claim is made.')
    (OUT/'REPORT.md').write_text('\n'.join(text)+'\n',encoding='utf-8')
    print('Generated REPORT.md and summary tables.')

if __name__=='__main__':main()
